import zones from './countryTimezones.json';

export interface CountryZone {
  id: string;
  en: string;
  fr: string;
  de: string;
  es: string;
}

/**
 * Country code → IANA zones. Data is `countryTimezones.json`, generated by
 * `scripts/generate-country-timezones.mjs` from tzdata `zone.tab` (allow-list
 * `iso3166.tab`). The same file is the server's zone list. A country with one
 * zone uses that zone. A country with several zones has no default.
 */
export const COUNTRY_ZONES: Record<string, readonly CountryZone[]> = zones;
